package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.Order;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/** Application service of PayOrder (legacy PAGOORD, including the PAGODEB debit rules). */
public class PayOrderService {

    // REQUIRES_EXTERNAL_DEFINITION: the 88-level values live in copybooks ORDREG / CTAREG that were not provided.
    private static final String ORDER_PENDING = "P";
    private static final String ACCOUNT_ACTIVE = "A";

    private static final BigDecimal LARGE_ORDER = new BigDecimal("50000");
    private static final BigDecimal COMMISSION_WEB = new BigDecimal("1.00");
    private static final BigDecimal COMMISSION_OTHER = new BigDecimal("2.50");
    private static final BigDecimal HUNDRED = new BigDecimal("100");
    private static final BigDecimal NINE_DIGITS = new BigDecimal("1000000000");

    private final OrderRepository orderRepository;
    private final AccountRepository accountRepository;
    private final MovementGateway movementGateway;

    public PayOrderService(OrderRepository orderRepository,
                           AccountRepository accountRepository,
                           MovementGateway movementGateway) {
        this.orderRepository = orderRepository;
        this.accountRepository = accountRepository;
        this.movementGateway = movementGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        // 2100-VALIDAR-ENTRADA
        String orderText = fixed(request.orderNumber(), 7);
        String accountType = fixed(request.accountType(), 3);
        String channel = fixed(request.channel(), 3);
        String key = fixed(request.approvalKey(), 6);

        if (!isNumeric(orderText) || isAllZeros(orderText)) {
            throw new BusinessError("INVALID_ORDER_NUMBER", "-1", "NUMERO DE ORDEN INVALIDO");
        }
        if (!accountType.equals("CTE") && !accountType.equals("AHO") && !accountType.equals("VIR")) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "-1", "TIPO DE CUENTA NO PERMITIDO");
        }
        if (!channel.equals("WEB") && !channel.equals("OFI")) {
            throw new BusinessError("CHANNEL_NOT_ALLOWED", "-1", "CANAL NO PERMITIDO");
        }
        if (channel.equals("OFI") && key.trim().isEmpty()) {
            throw new BusinessError("APPROVAL_KEY_REQUIRED", "-1", "CLAVE DE APROBACION REQUERIDA");
        }

        // 2200-LEER-ORDEN
        Integer orderNumber = Integer.valueOf(orderText);
        Integer companyId = Integer.valueOf(fixed(request.companyId(), 5).trim());
        Optional<Order> found = orderRepository.findByKey(orderNumber, companyId);
        if (found.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", "-1", "ORDEN NO EXISTE");
        }
        Order order = found.get();
        if (!ORDER_PENDING.equals(order.status())) {
            throw new BusinessError("ORDER_NOT_PENDING", "-1", "ORDEN NO ESTA PENDIENTE");
        }
        BigDecimal enteredValue = parseAmount(request.amount());
        if (enteredValue.compareTo(order.value()) != 0) {
            throw new BusinessError("AMOUNT_MISMATCH", "-1", "VALOR NO COINCIDE CON LA ORDEN");
        }

        // 2300-CALCULAR-COMISION
        BigDecimal commission;
        if (order.value().compareTo(LARGE_ORDER) >= 0) {
            commission = new BigDecimal("0.00");
        } else if (channel.equals("WEB")) {
            commission = COMMISSION_WEB;
        } else {
            commission = COMMISSION_OTHER;
        }
        BigDecimal total = order.value().add(commission);

        // 2400-DEBITAR-CUENTA (PAGODEB rules)
        Long accountNumber = Long.valueOf(fixed(request.accountNumber(), 10).trim());
        debit(accountNumber, accountType, total);

        // 2500-REGISTRAR-PAGO
        long movementNumber = movementGateway.registerMovement(order.orderNumber());
        orderRepository.markPaid(order.orderNumber(), order.companyId(), movementNumber, commission);

        // 2600-ENVIAR-RESULTADO
        return new PayOrderResponse(order.orderNumber(), commission, movementNumber, "PAGO REALIZADO");
    }

    private void debit(Long accountNumber, String accountType, BigDecimal amount) {
        Optional<Account> found = accountRepository.findByNumber(accountNumber);
        if (found.isEmpty()) {
            throw new BusinessError("INVALID_ACCOUNT", "30/40", "CUENTA NO VALIDA");
        }
        Account account = found.get();
        if (!fixed(account.accountType(), 3).equals(accountType)) {
            throw new BusinessError("INVALID_ACCOUNT", "30/40", "CUENTA NO VALIDA");
        }
        if (!ACCOUNT_ACTIVE.equals(account.status())) {
            throw new BusinessError("ACCOUNT_INACTIVE", "10", "CUENTA INACTIVA");
        }
        if (account.balance().compareTo(amount) < 0) {
            throw new BusinessError("INSUFFICIENT_FUNDS", "20", "SALDO INSUFICIENTE");
        }
        accountRepository.updateBalance(accountNumber, account.balance().subtract(amount));
    }

    /**
     * FUNCTION NUMVAL(VALORI) / 100 into PIC S9(9)V99 (truncated, no ROUNDED).
     * Per design: an explicit decimal point is taken as written, digits only are read with two implied decimals.
     * Blank or unparsable text yields zero (NUMVAL result).
     */
    private static BigDecimal parseAmount(String text) {
        String t = text == null ? "" : text.trim();
        BigDecimal value;
        if (t.isEmpty()) {
            value = BigDecimal.ZERO;
        } else {
            try {
                BigDecimal parsed = new BigDecimal(t);
                value = t.indexOf('.') >= 0 ? parsed : parsed.divide(HUNDRED);
            } catch (NumberFormatException e) {
                value = BigDecimal.ZERO;
            }
        }
        value = value.setScale(2, RoundingMode.DOWN);
        return value.remainder(NINE_DIGITS);
    }

    /** Fixed-length alphanumeric field: padded with spaces on the right or truncated. Null is blank. */
    private static String fixed(String value, int length) {
        String v = value == null ? "" : value;
        if (v.length() >= length) {
            return v.substring(0, length);
        }
        StringBuilder sb = new StringBuilder(v);
        while (sb.length() < length) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static boolean isNumeric(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return !s.isEmpty();
    }

    private static boolean isAllZeros(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != '0') {
                return false;
            }
        }
        return true;
    }
}

